/// Reference tables rendered by the Katsuyou reference view (generated by the engines, not bundled PDFs).
public enum ConjugationReference {
    /// The 12 verbs of the course conjugation chart, in chart order.
    public static let verbs: [Lexeme] = [
        ("かう", LexemeKind.godan), ("まつ", .godan), ("とる", .godan), ("よむ", .godan), ("あそぶ", .godan),
        ("しぬ", .godan), ("かく", .godan), ("およぐ", .godan), ("いく", .godan), ("はなす", .godan),
        ("たべる", .ichidan), ("みる", .ichidan), ("する", .suruKuru), ("くる", .suruKuru),
    ].map { Lexeme(headword: $0.0, reading: $0.0, kind: $0.1) }

    /// One word per type for the plain/polite matrix: noun, verb, na-adjective, i-adjective.
    public static let matrixLexemes: [(title: String, lexeme: Lexeme)] = [
        ("Noun", Lexeme(headword: "いしゃ", reading: "いしゃ", kind: .noun)),
        ("Verb", Lexeme(headword: "おきる", reading: "おきる", kind: .ichidan)),
        ("Na-adj", Lexeme(headword: "しずか", reading: "しずか", kind: .naAdj)),
        ("I-adj", Lexeme(headword: "ふるい", reading: "ふるい", kind: .iAdj)),
    ]

    public static func verbRow(_ lexeme: Lexeme) -> [String] {
        VerbForm.allCases.map { KatsuyouEngine.conjugate(lexeme, form: $0)?.display ?? "-" }
    }

    public static func matrixRow(_ lexeme: Lexeme) -> [String] {
        InflectionCell.all.map { InflectionEngine.inflect(lexeme, cell: $0).display }
    }
}
